use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn analyze_source_file_generic (src : & str , scan_len : usize , output_offset : TextSize , lines : & mut Vec < TextSize > , multi_byte_chars : & mut IntMap < u32 , Vec < WideChar > > ,) -> usize { assert ! (src . len () >= scan_len) ; let mut i = 0 ; let src_bytes = src . as_bytes () ; while i < scan_len { let byte = unsafe { * src_bytes . get_unchecked (i) } ; let mut char_len = 1 ; if byte == b'\n' { lines . push (TextSize :: from (i as u32 + 1) + output_offset) ; } else if byte >= 127 { let c = src [i ..] . chars () . next () . unwrap () ; char_len = c . len_utf8 () ; let pos = TextSize :: from (i as u32) + output_offset - lines . last () . unwrap_or (& TextSize :: default ()) ; if char_len > 1 { assert ! ((2 ..= 4) . contains (& char_len)) ; let mbc = WideChar { start : pos , end : pos + TextSize :: from (char_len as u32) , } ; multi_byte_chars . entry (lines . len () as u32) . or_default () . push (mbc) ; } } i += char_len ; } i - scan_len }